import unittest
from hourglass.rounding import round_spans, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_spans([Span(544, 1034)], 15)
        self.assertEqual(result, [Span(540, 1035)])

    def test_half_step_rounds_up(self):
        result = round_spans([Span(8, 60)], 15)
        self.assertEqual(result, [Span(15, 60)])

    def test_end_can_reach_midnight(self):
        result = round_spans([Span(1000, 1439)], 30)
        self.assertEqual(result, [Span(990, 1440)])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(100, 200)]
        self.assertEqual(len(rounded_labels(spans, 5)), 2)

    def test_bad_step_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(0, 60)], 0)


if __name__ == "__main__":
    unittest.main()
